bookInfoRule.init:
@js:
book.bookUrl = baseUrl;
var toUrl = baseUrl
if(baseUrl.includes("data:;base64")){
toUrl=java.hexDecodeToString(result)
}
var tocUrl = String(toUrl).replace(/book/, "ajax_novels/chapterlist")

result=java.ajax(getRealyUrl(toUrl))
h = java.t2s(tzs(result)) 
java.setContent(h);
$ = _ => java.t2s(java.getString(_,result))
list={
html:result,
n:$("[property~=book_name]@content"),
a:$("[property$=author]@content"),
c:$("[property~=category|status|update_time]@content"),
k:$("div.booknav2 > p:nth-child(5)@text"),
l:$("[property~=latest_chapter_name|lastest_chapter_name]@content"),
i:$("p:nth-child(1)@html||[property$=description]@content"),
img:java.get("image")||$(".bookimg2 > img@src"),
toc:tocUrl
}
JSON.stringify(list)

source.header:
@js:
(()=>{
var v=source.getVariable(),
ua=java.getWebViewUA();
cookie = cache.get(`croxy ck_${getCacheKey(su)}`) ? cache.get(`croxy ck_${getCacheKey(su)}`) : ""; 
head={
	"User-Agent": ua,
	"X-Requested-With": "mark.via",
	"Cookie": `${cookie};zh_choose=s`,
	"Referer": baseUrl+"/"
	};
	source.putLoginHeader(JSON.stringify(head));
	return JSON.stringify(head)
})();

