source.loginJs:
function start (type) {
	cache.delete(`croxy host_${getCacheKey(su)}`);
	cache.delete(`croxy time_${getCacheKey(su)}`);
	cache.delete(`croxy ck_${getCacheKey(su)}`);
	cache.delete(`cxylock_${getCacheKey(su)}`); 
 cookie.removeCookie(source.bookSourceUrl)
	type==1?java.longToast("开启代理中…"):java.longToast("正在初始化...请稍等")
	initFn();
	type==1?java.toast("开启成功"):java.toast("初始化成功")
}
function dlfn(){
source.setVariable(1);
java.toast("启用了代理")
start(1)
}
function dlend(){
	java.toast("缓存已清空")
		cache.delete(`croxy host_${getCacheKey(su)}`);
	cache.delete(`croxy time_${getCacheKey(su)}`);
	cache.delete(`croxy ck_${getCacheKey(su)}`);
	cache.delete(`cxylock_${getCacheKey(su)}`); 
 cookie.removeCookie(source.bookSourceUrl)
source.setVariable(0);
java.toast("关闭了代理")
}

